WITH cleaned AS (SELECT *, ROUND(units / revenue, 2) AS revenue_per_unit FROM store_sales WHERE sale_date > TO_DATE('2023-07-29')), with_dims AS (SELECT src.*, s.city FROM cleaned src JOIN stores s ON src.store_id = s.id), base AS (SELECT *, revenue_per_unit * units AS revenue_per_unit_times_units FROM with_dims WHERE city IS NOT NULL), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY revenue_per_unit, id) AS event_seq, PERCENT_RANK() OVER w_running AS revenue_per_unit_percent_rank FROM base WINDOW w_running AS (PARTITION BY DATE_TRUNC('month', sale_date), city ORDER BY revenue_per_unit DESC NULLS FIRST)), joined AS (SELECT e.*, p.launch_date, p.stock_qty, p.category FROM scored e JOIN products p ON e.product_id = p.id) SELECT * FROM (SELECT id, store_id, revenue_per_unit_percent_rank, revenue, revenue_per_unit_times_units, revenue_per_unit FROM joined) src UNPIVOT (metric_value FOR metric_name IN (revenue_per_unit_percent_rank, revenue, revenue_per_unit_times_units AS REVENUE_PER_UNIT_TIMES_UNITS_VAL, revenue_per_unit));
